contract InvMutTest {
    C c;
    constructor() { c = new C(address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address recipient) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(recipient == address(this));
        uint cBefore = address(c).balance;
        uint before = address(this).balance;
        c.withdrawAll(recipient); if (__ESBMC_reverted()) return;
        assert(address(c).balance == 0 && address(this).balance == before + cBefore);
    }
    receive() external payable {}
}

