// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Phishable c;

    function setUp() public {
        c = new Phishable(address(this));
    }

    function _run(address recipient) internal {
        vm.deal(address(c), VALUE_CAP);
        recipient = address(this);
        uint cBefore = address(c).balance;
        uint before = address(this).balance;
        try c.withdrawAll(recipient) {} catch { return; }
        assertTrue(address(c).balance == 0 && address(this).balance == before + cBefore);
    }

    function testFuzz_run(address recipient) public {
        _run(recipient);
    }

    receive() external payable {}
}
